166	// AccountStatus implements harnesses.AccountHarness. Claude-tui embeds
167	// account/plan info inside its quota probe, so this method projects the
168	// quota cache's Account field onto AccountSnapshot.
169	func (h *Harness) AccountStatus(ctx context.Context, now time.Time) (harnesses.AccountSnapshot, error) {
170		if err := ctx.Err(); err != nil {
171			return harnesses.AccountSnapshot{}, err
172		}
173		snap, ok := anthropic.ReadClaudeQuota()
174		if !ok || snap == nil {
175			return harnesses.AccountSnapshot{Source: "cache"}, nil
176		}
177		return claudettuiAccountSnapshotFromQuotaSnapshot(snap, now), nil
178	}
179	
180	// RefreshAccount implements harnesses.AccountHarness by driving the
181	// quota probe (which carries account evidence) and projecting the
182	// resulting cached snapshot onto AccountSnapshot.
183	func (h *Harness) RefreshAccount(ctx context.Context) (harnesses.AccountSnapshot, error) {
184		if _, err := h.RefreshQuota(ctx); err != nil {
185			return harnesses.AccountSnapshot{}, err
186		}
187		return h.AccountStatus(ctx, time.Now())
188	}
189	
190	// AccountFreshness implements harnesses.AccountHarness.
191	func (h *Harness) AccountFreshness() time.Duration {
192		return claudettuiAccountFreshness
193	}
194	
195	// claudettuiQuotaStatusFromSnapshot projects the shared snapshot onto
196	// harnesses.QuotaStatus using the same logic as claude.
197	func claudettuiQuotaStatusFromSnapshot(snap *anthropic.ClaudeQuotaSnapshot, now time.Time) harnesses.QuotaStatus {
198		status := harnesses.QuotaStatus{
199			Source:     snap.Source,
200			CapturedAt: snap.CapturedAt,
201			Fresh:      anthropic.IsClaudeQuotaFresh(snap, now, claudettuiQuotaFreshness),
202			Age:        anthropic.ClaudeQuotaSnapshotAge(snap, now),
203			Windows:    append([]harnesses.QuotaWindow(nil), snap.Windows...),
204		}
205	
206		// Determine RoutingPreference and State based on snapshot freshness and content
207		if status.Fresh {
208			// Fresh snapshot: check if we have headroom
209			status.State = harnesses.QuotaOK
210			status.RoutingPreference = harnesses.RoutingPreferenceAvailable
211		} else if snap != nil {
212			// Stale snapshot: assume limited
213			status.State = harnesses.QuotaStale
214			status.RoutingPreference = harnesses.RoutingPreferenceBlocked
215			status.Reason = "cached snapshot is stale; assume limited"
216		} else {
217			// No snapshot
218			status.State = harnesses.QuotaUnavailable
219			status.RoutingPreference = harnesses.RoutingPreferenceUnknown
220			status.Reason = "no cached snapshot"
221		}
222	
223		if snap.Account != nil {
224			acct := claudettuiAccountSnapshotFromQuotaSnapshot(snap, time.Now())
225			status.Account = &acct
226		}
227		return status
228	}
229	
230	// claudettuiAccountSnapshotFromQuotaSnapshot derives an AccountSnapshot from
231	// the quota cache's embedded Account field.
232	func claudettuiAccountSnapshotFromQuotaSnapshot(snap *anthropic.ClaudeQuotaSnapshot, now time.Time) harnesses.AccountSnapshot {
233		out := harnesses.AccountSnapshot{
234			Source:     "cache",
235			CapturedAt: snap.CapturedAt,
236			Fresh:      anthropic.IsClaudeQuotaFresh(snap, now, claudettuiAccountFreshness),
237		}
238		if snap.Account == nil {
239			return out
240		}
241		plan := strings.TrimSpace(snap.Account.PlanType)
242		out.PlanType = plan
243		out.Email = snap.Account.Email
244		out.OrgName = snap.Account.OrgName
245		switch {
246		case plan == "" || strings.EqualFold(plan, "unknown"):
247			out.Unauthenticated = true
248		default:
249			out.Authenticated = true
250		}
251		return out
252	}
