54	// HealthCheck implements harnesses.Harness.
55	func (h *Harness) HealthCheck(ctx context.Context) error {
56		_, err := exec.LookPath("claude")
57		if err != nil {
58			return fmt.Errorf("claude binary not found in PATH: %w", err)
59		}
60		return nil
61	}
62	
63	// Execute implements harnesses.Harness.
64	func (h *Harness) Execute(ctx context.Context, req harnesses.ExecuteRequest) (<-chan harnesses.Event, error) {
65		eventChan := make(chan harnesses.Event, 100)
66		go h.runTurn(ctx, req, eventChan)
67		return eventChan, nil
68	}
69	
70	// runTurn drives a single turn through the PTY using a pooled session, with /clear
71	// between turns to reset conversation history.
72	func (h *Harness) runTurn(ctx context.Context, req harnesses.ExecuteRequest, eventChan chan harnesses.Event) {
73		defer close(eventChan)
74	
75		logger := slog.Default()
76		startTime := time.Now()
77		seq := int64(0)
78	
79		// Resolve the claude binary path
80		claudePath, err := exec.LookPath("claude")
81		if err != nil {
82			seq++
83			emitFinalEvent(eventChan, seq, startTime, "error", fmt.Sprintf("claude binary not found: %v", err), 1)
84			return
85		}
86	
87		// Build environment allowlist per ADR-013
88		env := BuildEnvironmentAllowlist()
89	
90		// Create a temporary directory for hook payloads
91		hookDir, err := ioutil.TempDir("", "claude-tui-hooks-*")
92		if err != nil {
93			seq++
94			emitFinalEvent(eventChan, seq, startTime, "error", fmt.Sprintf("failed to create hook dir: %v", err), 1)
95			return
96		}
97		defer os.RemoveAll(hookDir)
98	
99		// Build hook configurations
100		hookPayloads := buildHookConfigs(hookDir)
101		settingsJSON, warnings := composeSettingsJSON(hookPayloads, logger)
102	
103		// Emit warnings as FinalWarning events if there were hook conflicts
104		if len(warnings) > 0 {
105			for _, w := range warnings {
106				seq++
107				fd := harnesses.FinalData{
108					Status: "hook_conflict",
109					Warnings: []harnesses.FinalWarning{{
110						Code:    "hook_conflict",
111						Message: w,
112					}},
113					DurationMS: time.Since(startTime).Milliseconds(),
114				}
115				data, _ := json.Marshal(fd)
116				eventChan <- harnesses.Event{
117					Type:     harnesses.EventTypeFinal,
118					Sequence: seq,
119					Time:     time.Now(),
120					Data:     data,
121				}
122			}
123		}
124	
125		// Build command args with --settings
126		args := []string{"--settings", settingsJSON}
127	
128		// Get or create pooled session
129		ptySession, err := getOrCreatePooledSession(
130			ctx,
131			"claude-tui",
132			claudePath,
133			args,
134			req.WorkDir,
135			env,
136			session.Size{Rows: 50, Cols: 220},
137		)
138		if err != nil {
139			seq++
140			emitFinalEvent(eventChan, seq, startTime, "error", fmt.Sprintf("failed to get pooled session: %v", err), 1)
141			return
142		}
143	
144		// Release or evict session based on execution result
145		defer func() {
146			// If we got the session but execution failed partway, release it for potential reuse
147			// The next Execute may try /clear which could fail, causing eviction
148			releasePooledSession("claude-tui", req.WorkDir, ptySession)
149		}()
150	
151		// For pooled sessions after the first one, try /clear to reset conversation history
152		if isPooledSessionReuse(ptySession) {
153			logger.Debug("clearing pooled session for new turn")
154			if err := clearSession(ptySession, "❯", 5*time.Second); err != nil {
155				logger.Warn("failed to clear session, evicting from pool", "error", err)
156				evictPooledSession("claude-tui", req.WorkDir, ptySession)
157				// Get a fresh session
158				ptySession, err = getOrCreatePooledSession(
159					ctx,
160					"claude-tui",
161					claudePath,
162					args,
163					req.WorkDir,
164					env,
165					session.Size{Rows: 50, Cols: 220},
166				)
167				if err != nil {
168					seq++
169					emitFinalEvent(eventChan, seq, startTime, "error", fmt.Sprintf("failed to get fresh session after /clear failure: %v", err), 1)
170					return
171				}
172			}
173		}
174	
175		// Start the startup probe responder for Ink startup (re-run after /clear)
176		responder := probes.New(probes.Config{
177			Session:      ptySession,
178			ReadyMarkers: []string{"❯", "> "},
179			Timeout:      10 * time.Second,
180		})
181		defer responder.Stop()
182	
183		deadline := time.Now().Add(10 * time.Second)
184		if err := responder.Ready(deadline); err != nil {
185			logger.Debug("startup probe timeout (non-fatal)", "error", err)
186		}
187	
188		// Send prompt via bracketed paste
189		promptBytes := []byte(req.Prompt)
190		bracketedPaste := append([]byte("\x1b[200~"), promptBytes...)
191		bracketedPaste = append(bracketedPaste, []byte("\x1b[201~\r")...)
192	
193		if err := ptySession.SendBytes(bracketedPaste); err != nil {
194			seq++
195			emitFinalEvent(eventChan, seq, startTime, "error", fmt.Sprintf("failed to send prompt: %v", err), 1)
196			return
197		}
198	
199		// Monitor for Stop hook payload to get transcript path
200		var transcriptPath string
201		stopHookPayloadFile := filepath.Join(hookDir, "stop-hook-payload.json")
202	
203		// Process PTY output and wait for stop hook
204		turnTimeout := time.NewTimer(5 * time.Minute)
205		defer turnTimeout.Stop()
206	
207		for {
208			select {
209			case <-ctx.Done():
210				_ = ptySession.Kill()
211				seq++
212				emitFinalEvent(eventChan, seq, startTime, "cancelled", "", 130)
213				return
214	
215			case chunk, ok := <-ptySession.Output():
216				if !ok {
217					// PTY closed, check for stop hook payload
218					if transcriptPath, err = readStopHookPayload(stopHookPayloadFile); err != nil {
219						logger.Debug("stop hook payload not found, continuing without transcript", "error", err)
220					}
221					// Process transcript if available
222					if transcriptPath != "" {
223						if err := h.emitTranscriptEvents(ctx, transcriptPath, eventChan, &seq, startTime); err != nil {
224							logger.Warn("failed to read transcript", "path", transcriptPath, "error", err)
225						}
226					}
227	
228					// Emit final event
229					seq++
230					emitFinalEvent(eventChan, seq, startTime, "success", "", 0)
231					return
232				}
233	
234				// Handle escape key to cancel
235				if chunk.Bytes != nil && bytes.Contains(chunk.Bytes, []byte("\x1b")) {
236					_ = ptySession.SendKey(session.KeyEscape)
237					continue
238				}
239	
240				turnTimeout.Reset(5 * time.Minute)
241	
242			case <-turnTimeout.C:
243				_ = ptySession.Kill()
244				seq++
245				emitFinalEvent(eventChan, seq, startTime, "error", "turn timeout exceeded", 124)
246				return
247			}
248		}
249	}
