408	// Shutdown enumerates live PTY sessions in the pool and reaps each one
409	// within a bounded timeout, sending SIGTERM and escalating to SIGKILL
410	// if the process does not exit cleanly.
411	func (h *Harness) Shutdown(ctx context.Context) error {
412		const defaultTimeout = 10 * time.Second
413	
414		// Extract deadline from context or use a default timeout
415		deadline, ok := ctx.Deadline()
416		if !ok {
417			deadline = time.Now().Add(defaultTimeout)
418		}
419	
420		sessions := getLiveSessionsSnapshot()
421		if len(sessions) == 0 {
422			return nil
423		}
424	
425		// Distribute remaining time across sessions
426		remaining := time.Until(deadline)
427		if remaining <= 0 {
428			remaining = 100 * time.Millisecond
429		}
430		perSessionTimeout := remaining / time.Duration(len(sessions))
431		if perSessionTimeout < 100*time.Millisecond {
432			perSessionTimeout = 100 * time.Millisecond
433		}
434	
435		for _, s := range sessions {
436			if time.Until(deadline) <= 0 {
437				break
438			}
439			sessionCtx, cancel := context.WithTimeout(context.Background(), perSessionTimeout)
440			_ = reapSession(sessionCtx, s)
441			cancel()
442		}
443	
444		return nil
445	}
