503	var (
504		claudeFullModelPattern         = regexp.MustCompile(`\bclaude-[a-z0-9][a-z0-9._-]*\b`)
505		claudeFullFamilyVersionPattern = regexp.MustCompile(`\bclaude-(sonnet|opus|haiku)-([0-9]+)[.-]([0-9]{1,2})(?:\b|-)`)
506		claudeFamilyVersionPattern     = regexp.MustCompile(`\b(?:claude\s+)?(sonnet|opus|haiku)\s+([0-9]+(?:[.-][0-9]+){0,2})\b`)
507		claudeAliasPattern             = regexp.MustCompile(`(?m)(?:^|[\s'"])(sonnet|opus|haiku)(?:$|[\s'"])`)
508		claudeEffortPattern            = regexp.MustCompile(`--effort\s+<level>.*\(([^)]*)\)`)
509	)
510	
511	// ParseClaudeTuiModels extracts available model names from claude /model output.
512	func ParseClaudeTuiModels(text string) []string {
513		text = anthropic.StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
514		lower := strings.ToLower(text)
515		models := uniqueMatches(claudeFullModelPattern.FindAllString(lower, -1))
516		for _, match := range claudeFullFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
517			if len(match) > 3 {
518				models = appendUniqueString(models, match[1]+"-"+match[2]+"."+match[3])
519			}
520		}
521		for _, match := range claudeFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
522			if len(match) > 2 {
523				models = appendUniqueString(models, match[1]+"-"+strings.ReplaceAll(match[2], "-", "."))
524			}
525		}
526		for _, match := range claudeAliasPattern.FindAllStringSubmatch(lower, -1) {
527			if len(match) > 1 {
528				models = appendUniqueString(models, match[1])
529			}
530		}
531		return models
532	}
533	
534	// ParseClaudeTuiReasoningLevels extracts supported reasoning levels from help output.
535	func ParseClaudeTuiReasoningLevels(text string) []string {
536		text = anthropic.StripANSI(strings.ReplaceAll(text, "\n", " "))
537		m := claudeEffortPattern.FindStringSubmatch(text)
538		if len(m) < 2 {
539			return nil
540		}
541		parts := strings.Split(m[1], ",")
542		out := make([]string, 0, len(parts))
543		for _, part := range parts {
544			out = appendUniqueString(out, strings.TrimSpace(part))
545		}
546		return out
547	}
