583	// BuildEnvironmentAllowlist constructs the environment for the PTY session
584	// according to ADR-013 §Environment Allowlist.
585	func BuildEnvironmentAllowlist() []string {
586		allowedKeys := map[string]bool{
587			"HOME":    true,
588			"PATH":    true,
589			"USER":    true,
590			"LOGNAME": true,
591			"SHELL":   true,
592			"LANG":    true,
593			"LC_ALL":  true,
594			"TZ":      true,
595			"TERM":    true,
596		}
597	
598		// XDG_* variables are allowed
599		xdgAllowed := map[string]bool{
600			"XDG_CONFIG_HOME": true,
601			"XDG_DATA_HOME":   true,
602			"XDG_CACHE_HOME":  true,
603			"XDG_STATE_HOME":  true,
604			"XDG_RUNTIME_DIR": true,
605		}
606	
607		var env []string
608		currentEnv := os.Environ()
609	
610		// Pass through allowed variables from the operator environment
611		for _, kv := range currentEnv {
612			key := strings.SplitN(kv, "=", 2)[0]
613	
614			// Check exact match
615			if allowedKeys[key] {
616				env = append(env, kv)
617				continue
618			}
619	
620			// Check XDG_* prefix
621			if xdgAllowed[key] {
622				env = append(env, kv)
623				continue
624			}
625	
626			// Check CLAUDE_* prefix (operator pre-existing variables)
627			if strings.HasPrefix(key, "CLAUDE_") {
628				env = append(env, kv)
629				continue
630			}
631		}
632	
633		// Set TERM and locale defaults if not already present
634		hasTermSet := false
635		hasLangSet := false
636		hasLCAllSet := false
637	
638		for _, kv := range env {
639			if strings.HasPrefix(kv, "TERM=") {
640				hasTermSet = true
641			}
642			if strings.HasPrefix(kv, "LANG=") {
643				hasLangSet = true
644			}
645			if strings.HasPrefix(kv, "LC_ALL=") {
646				hasLCAllSet = true
647			}
648		}
649	
650		if !hasTermSet {
651			env = append(env, "TERM=xterm-256color")
652		}
653		if !hasLangSet {
654			env = append(env, "LANG=C.UTF-8")
655		}
656		if !hasLCAllSet {
657			env = append(env, "LC_ALL=C.UTF-8")
658		}
659	
660		return env
661	}
