672	func resolveClaudeTuiFamilyAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) string {
673		for _, model := range snapshot.Models {
674			modelLower := strings.ToLower(model)
675			familyLower := strings.ToLower(family)
676			if strings.Contains(modelLower, familyLower) {
677				return model
678			}
679		}
680		return ""
681	}
