30	// ModelDiscoveryCache memoizes in-process discovery snapshots by harness and
31	// source. The embedded source is populated from the registry's cassette-backed
32	// model lists; live PTY refresh is intentionally out of scope here.
33	type ModelDiscoveryCache struct {
34		mu      sync.Mutex
35		loader  ModelDiscoveryLoader
36		entries map[discoveryCacheKey]discoveryCacheEntry
37	}
38	
39	func NewModelDiscoveryCache(loader ModelDiscoveryLoader) *ModelDiscoveryCache {
40		if loader == nil {
41			loader = LoadEmbeddedModelDiscoverySnapshot
42		}
43		return &ModelDiscoveryCache{
44			loader:  loader,
45			entries: make(map[discoveryCacheKey]discoveryCacheEntry),
46		}
47	}
