49	func (c *ModelDiscoveryCache) Snapshot(harnessName, source string) (ModelDiscoverySnapshot, error) {
50		if c == nil {
51			c = NewModelDiscoveryCache(nil)
52		}
53		key := discoveryCacheKey{
54			harnessName: strings.TrimSpace(harnessName),
55			source:      strings.TrimSpace(source),
56		}
57		if key.source == "" {
58			key.source = EmbeddedDiscoverySource
59		}
60		c.mu.Lock()
61		if entry, ok := c.entries[key]; ok {
62			c.mu.Unlock()
63			return entry.snapshot, entry.err
64		}
65		loader := c.loader
66		c.mu.Unlock()
67	
68		snapshot, err := loader(key.harnessName, key.source)
69	
70		c.mu.Lock()
71		c.entries[key] = discoveryCacheEntry{snapshot: snapshot, err: err}
72		c.mu.Unlock()
73		return snapshot, err
74	}
