246	func ResolveRunnerReasoning(harnessName, requestedReasoning string) ReasoningActual {
247		return ResolveRunnerReasoningWithCache(defaultDiscoveryCache, harnessName, requestedReasoning)
248	}
249	
250	func ResolveRunnerReasoningWithCache(cache *ModelDiscoveryCache, harnessName, requestedReasoning string) ReasoningActual {
251		if cache == nil {
252			cache = defaultDiscoveryCache
253		}
254		resolution := ReasoningActual{
255			Harness:            strings.TrimSpace(harnessName),
256			RequestedReasoning: strings.TrimSpace(requestedReasoning),
257			Source:             string(reasoning.ResolutionSourceCaller),
258		}
259		policy, err := reasoning.ParseString(requestedReasoning)
260		if err != nil {
261			resolution.ResolvedReasoning = requestedReasoning
262			return resolution
263		}
264		if policy.Kind == reasoning.KindUnset || policy.Kind == reasoning.KindAuto {
265			resolution.Source = string(reasoning.ResolutionSourceDefault)
266		}
267	
268		snapshot, err := cache.Snapshot(harnessName, EmbeddedDiscoverySource)
269		if err != nil || len(snapshot.ReasoningLevels) == 0 {
270			resolution.ResolvedReasoning = adapterReasoningPolicy(policy, requestedReasoning)
271			return resolution
272		}
273		resolution.DiscoverySource = snapshot.Source
274		resolution.SupportedReasoning = append([]string(nil), snapshot.ReasoningLevels...)
275	
276		supported, err := reasoning.ResolveAgainstSupportedLevels(policy, snapshot.ReasoningLevels)
277		if err != nil {
278			resolution.ResolvedReasoning = adapterReasoningPolicy(policy, requestedReasoning)
279			return resolution
280		}
281		resolution.ResolvedReasoning = adapterReasoningPolicy(supported.Policy, requestedReasoning)
282		resolution.Source = string(supported.Source)
283		resolution.Reason = supported.Reason
284		resolution.Warning = supported.Warning
285		return resolution
286	}
287	
288	func adapterReasoningPolicy(policy reasoning.Policy, fallback string) string {
289		switch policy.Kind {
290		case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
291			return ""
292		case reasoning.KindTokens:
293			if policy.Tokens == 0 {
294				return ""
295			}
296			return string(policy.Value)
297		case reasoning.KindNamed:
298			return string(policy.Value)
299		default:
300			return fallback
301		}
302	}
