12	// claudeQuotaSnapshot is now a type alias to the neutral anthropic version.
13	type claudeQuotaSnapshot = anthropic.ClaudeQuotaSnapshot
14	
15	// defaultClaudeQuotaStaleAfter references the anthropic package constant.
16	const defaultClaudeQuotaStaleAfter = anthropic.DefaultClaudeQuotaStaleAfter
17	
18	// claudeQuotaCacheEnv lets tests override the cache file path.
19	const claudeQuotaCacheEnv = "FIZEAU_CLAUDE_QUOTA_CACHE"
20	
21	// claudeQuotaCachePath is now delegated to the anthropic package.
22	func claudeQuotaCachePath() (string, error) {
23		return anthropic.ClaudeQuotaCachePath()
24	}
25	
26	// writeClaudeQuota is now delegated to the anthropic package.
27	func writeClaudeQuota(path string, snapshot claudeQuotaSnapshot) error {
28		return anthropic.WriteClaudeQuota(path, snapshot)
29	}
30	
31	// readClaudeQuotaFrom is now delegated to the anthropic package.
32	func readClaudeQuotaFrom(path string) (*claudeQuotaSnapshot, bool) {
33		return anthropic.ReadClaudeQuotaFrom(path)
34	}
35	
36	// readClaudeQuota reads the cached snapshot from the default location.
37	// The second return value is false if no snapshot is present or cannot be
38	// decoded.
39	//
40	// Callers SHOULD check snapshot age via claudeQuotaSnapshotAge (or
41	// isClaudeQuotaFresh) before trusting the values; this function does not
42	// itself enforce a TTL so that callers can report stale snapshots in
43	// diagnostic surfaces like `ddx agent doctor --routing`.
44	func readClaudeQuota() (*claudeQuotaSnapshot, bool) {
45		return anthropic.ReadClaudeQuota()
46	}
47	
48	// claudeQuotaSnapshotAge reports the age of a snapshot relative to now.
49	// A zero or future CapturedAt yields a zero age.
50	func claudeQuotaSnapshotAge(snapshot *claudeQuotaSnapshot, now time.Time) time.Duration {
51		return anthropic.ClaudeQuotaSnapshotAge(snapshot, now)
52	}
53	
54	// isClaudeQuotaFresh reports whether a snapshot exists and is newer than
55	// staleAfter relative to now. A nil snapshot is never fresh. A zero
56	// staleAfter falls back to defaultClaudeQuotaStaleAfter.
57	func isClaudeQuotaFresh(snapshot *claudeQuotaSnapshot, now time.Time, staleAfter time.Duration) bool {
58		return anthropic.IsClaudeQuotaFresh(snapshot, now, staleAfter)
59	}
