61	// claudeQuotaRoutingDecision summarizes what foreground routing should do
62	// given the current cached snapshot.
63	type claudeQuotaRoutingDecision struct {
64		// PreferClaude is true when a fresh snapshot shows headroom in both the
65		// 5-hour and weekly windows. When false, routing should prefer a
66		// non-claude fallback harness.
67		PreferClaude bool
68		// SnapshotPresent is true when a snapshot was found in the cache (even
69		// if stale).
70		SnapshotPresent bool
71		// Fresh is true when the snapshot is present and newer than staleAfter.
72		Fresh bool
73		// Age is the age of the snapshot relative to now (zero when absent).
74		Age time.Duration
75		// Snapshot is the cached snapshot when present.
76		Snapshot *claudeQuotaSnapshot
77		// Reason describes why the decision was made (diagnostic surface).
78		Reason string
79	}
80	
81	// decideClaudeQuotaRouting turns a cached snapshot into a routing decision
82	// for foreground callers. When the snapshot is missing or stale, the safe
83	// default is NOT to prefer claude (assume limited).
84	//
85	// A snapshot counts as "limited" when either window reports zero or
86	// negative remaining headroom.
87	func decideClaudeQuotaRouting(snapshot *claudeQuotaSnapshot, now time.Time, staleAfter time.Duration) claudeQuotaRoutingDecision {
88		decision := claudeQuotaRoutingDecision{
89			Snapshot: snapshot,
90		}
91		if snapshot == nil {
92			decision.Reason = "no cached snapshot; assume limited"
93			return decision
94		}
95		decision.SnapshotPresent = true
96		decision.Age = claudeQuotaSnapshotAge(snapshot, now)
97		if !isClaudeQuotaFresh(snapshot, now, staleAfter) {
98			decision.Reason = "cached snapshot is stale; assume limited"
99			return decision
100		}
101		if err := validateClaudeQuotaSnapshotForRouting(snapshot); err != nil {
102			decision.Reason = "cached snapshot is incomplete: " + err.Error() + "; assume limited"
103			return decision
104		}
105		decision.Fresh = true
106		if exhausted := exhaustedClaudeQuotaWindow(snapshot.Windows); exhausted != "" {
107			decision.Reason = "fresh snapshot reports exhausted " + exhausted + " window; assume limited"
108			return decision
109		}
110		if snapshot.FiveHourRemaining <= 0 || snapshot.WeeklyRemaining <= 0 {
111			decision.Reason = "fresh snapshot reports exhausted window; assume limited"
112			return decision
113		}
114		decision.PreferClaude = true
115		decision.Reason = "fresh snapshot has headroom"
116		return decision
117	}
