124			return fmt.Errorf("missing source")
125		}
126		if snapshot.Account == nil || strings.TrimSpace(snapshot.Account.PlanType) == "" {
127			return fmt.Errorf("missing account plan")
128		}
129		if snapshot.FiveHourLimit <= 0 {
130			return fmt.Errorf("invalid 5h limit")
131		}
132		if snapshot.WeeklyLimit <= 0 {
133			return fmt.Errorf("invalid weekly limit")
134		}
135		if snapshot.FiveHourRemaining < 0 || snapshot.FiveHourRemaining > snapshot.FiveHourLimit {
136			return fmt.Errorf("invalid 5h remaining")
137		}
138		if snapshot.WeeklyRemaining < 0 || snapshot.WeeklyRemaining > snapshot.WeeklyLimit {
139			return fmt.Errorf("invalid weekly remaining")
140		}
