301	// claudeAccountSnapshotFromQuotaSnapshot derives an AccountSnapshot from
302	// the quota cache's embedded Account field. Plan-type "unknown" (written
303	// by markClaudeQuotaExhaustedFromMessage on runtime errors) is reported
304	// as unauthenticated evidence rather than positive authentication.
305	func claudeAccountSnapshotFromQuotaSnapshot(snap *claudeQuotaSnapshot, now time.Time) harnesses.AccountSnapshot {
306		out := harnesses.AccountSnapshot{
307			Source:     "cache",
308			CapturedAt: snap.CapturedAt,
309			Fresh:      isClaudeQuotaFresh(snap, now, claudeAccountFreshness),
310		}
311		if snap.Account == nil {
312			return out
313		}
314		plan := strings.TrimSpace(snap.Account.PlanType)
315		out.PlanType = plan
316		out.Email = snap.Account.Email
317		out.OrgName = snap.Account.OrgName
318		switch {
319		case plan == "" || strings.EqualFold(plan, "unknown"):
320			out.Unauthenticated = true
321		default:
322			out.Authenticated = true
323		}
324		return out
325	}
