38			Args:         cfg.args,
39			Workdir:      cfg.workdir,
40			Env:          cfg.env,
41			Command:      "/model\r",
42			ReadyMarkers: []string{"❯", "> "},
43			DoneWhen:     claudeModelDiscoveryComplete,
44			Timeout:      timeout,
45			Size:         session.Size{Rows: 50, Cols: 220},
