276	func uniqueMatches(values []string) []string {
277		out := make([]string, 0, len(values))
278		for _, value := range values {
279			out = appendUniqueString(out, value)
280		}
281		return out
282	}
283	
284	func appendUniqueString(values []string, value string) []string {
285		value = strings.TrimSpace(value)
286		if value == "" {
287			return values
288		}
289		for _, existing := range values {
290			if existing == value {
291				return values
292			}
293		}
294		return append(values, value)
295	}
