// === Model Discovery Cache (ADR-012) ===

const (
	// claudeTuiModelDiscoveryFreshnessWindow is the TTL for cached model discovery.
	claudeTuiModelDiscoveryFreshnessWindow = 24 * time.Hour
	// defaultModelDiscoveryTimeout is the default timeout for live PTY discovery.
	defaultModelDiscoveryTimeout = 30 * time.Second
)

// modelDiscoveryCacheSnapshot holds the cached model discovery state.
type modelDiscoveryCacheSnapshot struct {
	Snapshot   harnesses.ModelDiscoverySnapshot `json:"snapshot"`
	CapturedAt time.Time                        `json:"captured_at"`
}

// discoveryGroup serializes concurrent DefaultModelSnapshot calls
// across all *Harness instances via single-flight per ADR-012.
var (
	discoveryGroup       singleflight.Group
	discoveryMu          sync.Mutex
	discoveryProbeCalls  int // for testing only
)

// ModelDiscoveryProbeFunc is the signature of the live PTY probe.
type ModelDiscoveryProbeFunc func(ctx context.Context, timeout time.Duration) (harnesses.ModelDiscoverySnapshot, error)

// captureModelDiscoveryProbe is the live PTY probe used by DefaultModelSnapshot.
var captureModelDiscoveryProbe ModelDiscoveryProbeFunc = func(ctx context.Context, timeout time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
	return readClaudeTuiModelDiscoveryViaPTY(ctx, timeout)
}

// SetModelDiscoveryProbeForTest swaps the probe for testing and resets the discovery group.
func SetModelDiscoveryProbeForTest(fn ModelDiscoveryProbeFunc) func() {
	prev := captureModelDiscoveryProbe
	captureModelDiscoveryProbe = fn
	discoveryGroup.Forget("claudetui:model-discovery")
	return func() {
		captureModelDiscoveryProbe = prev
		discoveryGroup.Forget("claudetui:model-discovery")
	}
}

// getModelDiscoveryCachePath returns the on-disk cache path for model discovery.
func getModelDiscoveryCachePath() (string, error) {
	baseDir, err := os.UserCacheDir()
	if err != nil {
		return "", fmt.Errorf("cannot determine cache dir: %w", err)
	}
	cacheDir := filepath.Join(baseDir, "fizeau", "discovery")
	if err := os.MkdirAll(cacheDir, 0o700); err != nil {
		return "", fmt.Errorf("cannot create cache dir: %w", err)
	}
	return filepath.Join(cacheDir, "claude-tui.json"), nil
}

// readModelDiscoveryCache reads the cached snapshot from disk.
func readModelDiscoveryCache() (*modelDiscoveryCacheSnapshot, error) {
	path, err := getModelDiscoveryCachePath()
	if err != nil {
		return nil, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("read cache: %w", err)
	}
	var snap modelDiscoveryCacheSnapshot
	if err := json.Unmarshal(data, &snap); err != nil {
		return nil, fmt.Errorf("decode cache: %w", err)
	}
	return &snap, nil
}

// writeModelDiscoveryCache writes the snapshot to the cache file atomically.
func writeModelDiscoveryCache(snap *modelDiscoveryCacheSnapshot) error {
	path, err := getModelDiscoveryCachePath()
	if err != nil {
		return err
	}
	data, err := json.MarshalIndent(snap, "", "  ")
	if err != nil {
		return fmt.Errorf("encode cache: %w", err)
	}
	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0o600); err != nil {
		return fmt.Errorf("write temp cache: %w", err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		return fmt.Errorf("commit cache: %w", err)
	}
	return nil
}

// isCacheFresh checks if a snapshot is still valid per the freshness window.
func isCacheFresh(snap *modelDiscoveryCacheSnapshot) bool {
	if snap == nil {
		return false
	}
	age := time.Since(snap.CapturedAt)
	return age >= 0 && age < claudeTuiModelDiscoveryFreshnessWindow
}

// incModelDiscoveryProbeCallsForTest increments the probe call counter (testing only).
func incModelDiscoveryProbeCallsForTest() {
	discoveryMu.Lock()
	discoveryProbeCalls++
	discoveryMu.Unlock()
}

