// ErrModelDiscoveryEvidenceMissing on PTY failure or empty snapshot.
func (h *Harness) DefaultModelSnapshot() harnesses.ModelDiscoverySnapshot {
	v, err, _ := discoveryGroup.Do("claudetui:model-discovery", func() (any, error) {
		return h.defaultModelSnapshotLocked()
	})
	if err != nil {
		return harnesses.ModelDiscoverySnapshot{}
	}
	return v.(harnesses.ModelDiscoverySnapshot)
}

// defaultModelSnapshotLocked is the single-flight critical section for model discovery.
// It reads fresh cache if available, or probes PTY, caches the result, and returns the snapshot.
func (h *Harness) defaultModelSnapshotLocked() (harnesses.ModelDiscoverySnapshot, error) {
	// Try to read from cache first
	cached, err := readModelDiscoveryCache()
	if err == nil && cached != nil && isCacheFresh(cached) {
		return cached.Snapshot, nil
	}

	// Probe live PTY with configurable timeout
	ctx := context.Background()
	timeout := defaultModelDiscoveryTimeout
	snapshot, err := captureModelDiscoveryProbe(ctx, timeout)
	incModelDiscoveryProbeCallsForTest()
	if err != nil {
		return harnesses.ModelDiscoverySnapshot{}, err
	}
	if len(snapshot.Models) == 0 {
		return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
	}

	// Cache the successful snapshot
	cacheSnap := &modelDiscoveryCacheSnapshot{
		Snapshot:   snapshot,
		CapturedAt: time.Now(),
	}
	_ = writeModelDiscoveryCache(cacheSnap)

	return snapshot, nil
}

// ResolveModelAlias implements harnesses.ModelDiscoveryHarness.
// Resolves a family name (sonnet, opus, haiku) to a concrete model ID from the snapshot.
// Returns ErrAliasNotResolvable if the family is not recognized or not found in snapshot.
func (h *Harness) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
	normalized := strings.ToLower(strings.TrimSpace(family))
	if !isSupportedClaudeTuiAlias(normalized) {
		return "", harnesses.ErrAliasNotResolvable
	}
	resolved := resolveClaudeTuiFamilyAlias(normalized, snapshot)
	if resolved == "" {
		return "", harnesses.ErrAliasNotResolvable
	}
	return resolved, nil
}

// SupportedAliases implements harnesses.ModelDiscoveryHarness.
// Returns the stable set of family aliases this harness recognizes.
func (h *Harness) SupportedAliases() []string {
	return append([]string(nil), supportedAliases...)
}

// isSupportedClaudeTuiAlias checks if a family is in the supported set.
func isSupportedClaudeTuiAlias(family string) bool {
	for _, a := range supportedAliases {
		if a == family {
			return true
		}
	}
	return false
}

// resolveClaudeTuiFamilyAlias finds the best concrete model matching the family in the snapshot.
func resolveClaudeTuiFamilyAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) string {
	for _, model := range snapshot.Models {
		modelLower := strings.ToLower(model)
		if strings.Contains(modelLower, family) {
			return model
		}
	}
	return ""
}

